  count: {{ . }}
  {{- end }}
  {{- $esRef := or ((.Values.spec).elasticsearchRef) (.Values.elasticsearchRef) }}
  {{- if not ($esRef).name }}
  {{ fail "An elasticsearchRef is required" }}
  {{- end }}
  elasticsearchRef:
  {{- toYaml $esRef | nindent 4 }}
  {{- $entsearchRef := or ((.Values.spec).enterpriseSearchRef) (.Values.enterpriseSearchRef) }}
