    {{- toYaml . | nindent 4 }}
  {{- end }}
  {{- with or ((.Values.spec).serviceAccountName) (.Values.serviceAccountName) }}
  serviceAccountName: {{ . }}
  {{- end }}
  {{- with or ((.Values.spec).monitoring) (.Values.monitoring) }}
  monitoring:
    {{- toYaml . | nindent 4 }}
  {{- end }}

